/work/src/domain/bookmarkSearch.ts.content:
import type { Bookmark } from './bookmark'
import { comparisonKey } from './tagNormalization'

export interface TagSummary {
  label: string
  comparisonKey: string
  bookmarkCount: number
}

export function newestFirst(bookmarks: Bookmark[]): Bookmark[] {
  return [...bookmarks].sort((a, b) =>
    b.createdAt.localeCompare(a.createdAt) || a.id.localeCompare(b.id),
  )
}

export function filterBookmarks(
  bookmarks: Bookmark[],
  query: string,
  tag: string,
): Bookmark[] {
  const q = comparisonKey(query)
  const tagKey = comparisonKey(tag)
  return newestFirst(bookmarks).filter((bookmark) => {
    const matchesTag = !tagKey || bookmark.tags.some((item) => comparisonKey(item) === tagKey)
    const haystack = [bookmark.title, bookmark.url, bookmark.description, ...bookmark.tags]
      .map(comparisonKey)
      .join('\n')
    return matchesTag && (!q || haystack.includes(q))
  })
}

export function deriveTags(bookmarks: Bookmark[]): TagSummary[] {
  const tags = new Map<string, TagSummary>()
  for (const bookmark of bookmarks) {
    for (const label of bookmark.tags) {
      const key = comparisonKey(label)
      const current = tags.get(key)
      if (current) current.bookmarkCount += 1
      else tags.set(key, { label, comparisonKey: key, bookmarkCount: 1 })
    }
  }
  return [...tags.values()].sort((a, b) => a.label.localeCompare(b.label))
}

/work/src/components/BookmarkCard.tsx.content:
import type { Bookmark } from '../domain/bookmark'

interface BookmarkCardProps {
  bookmark: Bookmark
  onEdit: (bookmark: Bookmark, trigger: HTMLElement) => void
  onDelete: (bookmark: Bookmark, trigger: HTMLElement) => void
}

function hostname(url: string) {
  return new URL(url).hostname.replace(/^www\./, '')
}

export function BookmarkCard({ bookmark, onEdit, onDelete }: BookmarkCardProps) {
  return (
    <article className="bookmark-card">
      <div className="card-topline">
        <span className="site-monogram" aria-hidden="true">{hostname(bookmark.url).charAt(0).toUpperCase()}</span>
        <span className="site-host">{hostname(bookmark.url)}</span>
        <div className="card-actions">
          <button type="button" className="icon-button" aria-label={`Edit ${bookmark.title}`} onClick={(event) => onEdit(bookmark, event.currentTarget)}>Edit</button>
          <button type="button" className="icon-button danger-text" aria-label={`Delete ${bookmark.title}`} onClick={(event) => onDelete(bookmark, event.currentTarget)}>Delete</button>
        </div>
      </div>
      <h2>
        <a href={bookmark.url} target="_blank" rel="noopener noreferrer">
          {bookmark.title}<span className="sr-only"> (opens in a new tab)</span>
        </a>
      </h2>
      {bookmark.description && <p className="description">{bookmark.description}</p>}
      <div className="card-footer">
        <div className="tag-row" aria-label="Tags">
          {bookmark.tags.map((tag) => <span className="tag" key={tag}>{tag}</span>)}
        </div>
        <time dateTime={bookmark.createdAt}>Saved {new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(bookmark.createdAt))}</time>
      </div>
    </article>
  )
}

/work/src/components/BookmarkList.tsx.content:
import type { Bookmark } from '../domain/bookmark'
import { BookmarkCard } from './BookmarkCard'

interface BookmarkListProps {
  bookmarks: Bookmark[]
  onEdit: (bookmark: Bookmark, trigger: HTMLElement) => void
  onDelete: (bookmark: Bookmark, trigger: HTMLElement) => void
}

export function BookmarkList({ bookmarks, onEdit, onDelete }: BookmarkListProps) {
  return (
    <div className="bookmark-grid">
      {bookmarks.map((bookmark) => (
        <BookmarkCard key={bookmark.id} bookmark={bookmark} onEdit={onEdit} onDelete={onDelete} />
      ))}
    </div>
  )
}

/work/src/components/SearchAndFilter.tsx.content:
import type { TagSummary } from '../domain/bookmarkSearch'

interface SearchAndFilterProps {
  query: string
  tag: string
  tags: TagSummary[]
  resultCount: number
  totalCount: number
  onQueryChange: (value: string) => void
  onTagChange: (value: string) => void
  onClear: () => void
}

export function SearchAndFilter(props: SearchAndFilterProps) {
  const active = Boolean(props.query || props.tag)
  return (
    <section className="finder" aria-label="Find bookmarks">
      <div className="search-field">
        <span aria-hidden="true">⌕</span>
        <label className="sr-only" htmlFor="bookmark-search">Search bookmarks</label>
        <input id="bookmark-search" type="search" value={props.query} onChange={(event) => props.onQueryChange(event.target.value)} placeholder="Search titles, notes, links, or tags…" />
        {props.query && <button type="button" aria-label="Clear search" onClick={() => props.onQueryChange('')}>×</button>}
      </div>
      <label className="select-field">
        <span className="sr-only">Filter by tag</span>
        <select value={props.tag} onChange={(event) => props.onTagChange(event.target.value)}>
          <option value="">All tags</option>
          {props.tags.map((tag) => <option value={tag.label} key={tag.comparisonKey}>{tag.label} ({tag.bookmarkCount})</option>)}
        </select>
      </label>
      {active && <button className="clear-button" type="button" onClick={props.onClear}>Clear all</button>}
      <p className="result-count" aria-live="polite">Showing {props.resultCount} of {props.totalCount}</p>
    </section>
  )
}

/work/src/components/ConfirmDialog.tsx.content:
import { useEffect, useRef } from 'react'

interface ConfirmDialogProps {
  title: string
  children: React.ReactNode
  confirmLabel: string
  destructive?: boolean
  busy?: boolean
  onConfirm: () => void
  onCancel: () => void
}

export function ConfirmDialog({ title, children, confirmLabel, destructive, busy, onConfirm, onCancel }: ConfirmDialogProps) {
  const dialogRef = useRef<HTMLDialogElement>(null)
  const cancelRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    dialogRef.current?.showModal()
    cancelRef.current?.focus()
  }, [])

  return (
    <dialog ref={dialogRef} className="dialog" aria-labelledby="confirm-title" onCancel={(event) => { event.preventDefault(); onCancel() }}>
      <form method="dialog" onSubmit={(event) => event.preventDefault()}>
        <p className="eyebrow">Please confirm</p>
        <h2 id="confirm-title">{title}</h2>
        <div className="dialog-copy">{children}</div>
        <div className="dialog-actions">
          <button ref={cancelRef} className="button secondary" type="button" onClick={onCancel} disabled={busy}>Cancel</button>
          <button className={`button ${destructive ? 'danger' : 'primary'}`} type="button" onClick={onConfirm} disabled={busy}>{busy ? 'Working…' : confirmLabel}</button>
        </div>
      </form>
    </dialog>
  )
}

/work/src/components/EmptyState.tsx.content:
interface EmptyStateProps {
  filtered?: boolean
  onAction: () => void
}

export function EmptyState({ filtered = false, onAction }: EmptyStateProps) {
  return (
    <section className="empty-state" aria-labelledby="empty-title">
      <div className="empty-mark" aria-hidden="true">↗</div>
      <p className="eyebrow">{filtered ? 'Nothing here yet' : 'A fresh collection'}</p>
      <h2 id="empty-title">{filtered ? 'No bookmarks match that' : 'Save your first good find'}</h2>
      <p>{filtered ? 'Try a different search or clear your filters to see everything.' : 'Keep links worth returning to, then find them by a word or a tag.'}</p>
      <button className="button primary" type="button" onClick={onAction}>
        {filtered ? 'Clear search and filter' : 'Add your first bookmark'}
      </button>
    </section>
  )
}

