import { describe, expect, it } from 'vitest'
import { normalizeUrl, validateBookmarkInput } from '../../src/domain/urlNormalization'

describe('URL and bookmark validation', () => {
  it('trims and adds HTTPS', () => expect(normalizeUrl(' example.com/path ')).toBe('https://example.com/path'))
  it('preserves HTTP and meaningful URL parts', () => expect(normalizeUrl('http://EXAMPLE.com:80/a?q=1#x')).toBe('http://example.com/a?q=1#x'))
  it.each(['', 'not a host', 'javascript:alert(1)', 'ftp://example.com'])('rejects %s', (value) => expect(() => normalizeUrl(value)).toThrow())
  it('requires a title and trims all fields', () => {
    const invalid = validateBookmarkInput({ title: ' ', url: 'example.com', description: '', tags: [] })
    expect(invalid.ok).toBe(false)
    const valid = validateBookmarkInput({ title: ' Example ', url: 'example.com', description: ' Note ', tags: [' Work '] })
    expect(valid).toEqual({ ok: true, value: { title: 'Example', url: 'https://example.com/', description: 'Note', tags: ['Work'] } })
  })
})

/work/tests/unit/bookmarkSearch.test.ts.content:
import { describe, expect, it } from 'vitest'
import type { Bookmark } from '../../src/domain/bookmark'
import { deriveTags, filterBookmarks } from '../../src/domain/bookmarkSearch'

const make = (id: string, title: string, tags: string[] = [], description = ''): Bookmark => ({ id, title, url: `https://${id}.example.com/`, description, tags, createdAt: `2026-01-0${id}T00:00:00.000Z`, updatedAt: `2026-01-0${id}T00:00:00.000Z` })
const data = [make('1', 'Design systems', ['Work', 'Design']), make('2', 'Weekend recipe', ['Home'], 'Olive bread')]

describe('bookmark discovery', () => {
  it('searches every field without case sensitivity', () => {
    expect(filterBookmarks(data, 'DESIGN', '')).toHaveLength(1)
    expect(filterBookmarks(data, 'olive', '')).toHaveLength(1)
    expect(filterBookmarks(data, '2.example', '')).toHaveLength(1)
  })
  it('combines query and one tag filter', () => expect(filterBookmarks(data, 'recipe', 'HOME').map(x => x.id)).toEqual(['2']))
  it('derives reusable tags and counts', () => expect(deriveTags([...data, make('3', 'Other', ['work'])]).find(x => x.comparisonKey === 'work')?.bookmarkCount).toBe(2))
  it('filters 1,000 items well below one second', () => {
    const many = Array.from({ length: 1000 }, (_, i) => make(String(i), `Bookmark ${i}`, [i % 2 ? 'Odd' : 'Even']))
    const start = performance.now()
    expect(filterBookmarks(many, '999', 'Odd')).toHaveLength(1)
    expect(performance.now() - start).toBeLessThan(1000)
  })
})

/work/tests/helpers.tsx.content:
import type { Bookmark, BookmarkInput, BookmarkRepository } from '../src/domain/bookmark'

export class MemoryRepository implements BookmarkRepository {
  items: Bookmark[]
  fail = false
  constructor(items: Bookmark[] = []) { this.items = items }
  async list() { return [...this.items] }
  async create(input: BookmarkInput) {
    if (this.fail) throw new Error('failed')
    const item = { ...input, id: String(this.items.length + 1), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }
    this.items.push(item); return item
  }
  async update(id: string, input: BookmarkInput) {
    if (this.fail) throw new Error('failed')
    const current = this.items.find(x => x.id === id)!
    const item = { ...current, ...input, id, createdAt: current.createdAt, updatedAt: new Date(Date.now() + 1000).toISOString() }
    this.items = this.items.map(x => x.id === id ? item : x); return item
  }
  async delete(id: string) { if (this.fail) throw new Error('failed'); this.items = this.items.filter(x => x.id !== id) }
}

export const sample: Bookmark = { id: '1', title: 'Example', url: 'https://example.com/', description: 'A useful reference', tags: ['Work'], createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-01T00:00:00.000Z' }

